{
  "name": "builder_gap_threshold_001",
  "intuition": "Filter out near-ties by requiring a minimum objective gap, reducing noisy or ambiguous preferences that can hurt generalization; keep all informative pairs above the configurable threshold.",
  "implementation_hint": {
    "expects": [
