  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Only create pairs when the objective gap is large enough to be meaningful.\n    gap_threshold = extra.get('gap_threshold', 0.0) if extra is not None else 0.0\n    diff = objective[:, :, None] - objective[:, None, :]\n    mask = diff < (-gap_threshold)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'gap_threshold', 'gap_threshold': float(gap_threshold)})\n"
