{
  "name": "rank_stratified_cap_no_int",
  "intuition": "Create deterministic, objective-driven pairwise preferences per instance by ranking candidates (lower objective is better) and comparing the best against tail/second/mid plus optional mid-vs-tail, capped to a fixed number of pairs without using forbidden builtins.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']  # [B, K], lower is better
    B, K = objective.shape

    # Avoid using int(); extra values are assumed numeric.
    max_pairs_per_instance = extra.get('max_pairs_per_instance', 8)
    if max_pairs_per_instance is None:
        max_pairs_per_instance = 8
    if max_pairs_per_instance < 1:
        max_pairs_per_instance = 1

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        if K < 2:
            continue

        order = objective[b].argsort(stable=True)
        pairs_added = 0

        def add_pair(win_idx, lose_idx):
            nonlocal pairs_added
            if pairs_added >= max_pairs_per_instance:
                return
            b_list.append(b)
            w_list.append(win_idx)
            l_list.append(lose_idx)
            pairs_added = pairs_added + 1

        best = order[0]
        tail = order[-1]
        add_pair(best, tail)  # guaranteed coverage when K>=2

        if K >= 3:
            add_pair(best, order[1])
        if K >= 4:
            add_pair(best, order[K // 2])
        if K >= 5:
            add_pair(order[K // 2], tail)

        # Fill remaining budget with increasing rank gaps: best beats rank 1,2,4,8,...
        step = 1
        while pairs_added < max_pairs_per_instance and step < (K - 1):
            lose_r = step
            if lose_r >= K:
                lose_r = K - 1
            add_pair(order[0], order[lose_r])
            step = step * 2

    # Build int64 1D indices on objective's device.
    dtype_i64 = objective.new_empty((0,), dtype=objective.dtype).long().dtype

    if len(b_list) == 0:
        empty = objective.new_empty((0,), dtype=dtype_i64)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'rank_stratified_cap_no_int', 'max_pairs_per_instance': max_pairs_per_instance}
        )

    b_idx = objective.new_tensor(b_list, dtype=dtype_i64)
    w_idx = objective.new_tensor(w_list, dtype=dtype_i64)
    l_idx = objective.new_tensor(l_list, dtype=dtype_i64)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={'builder': 'rank_stratified_cap_no_int', 'max_pairs_per_instance': max_pairs_per_instance}
    )
