{
  "name": "rank_adjacent_cap",
  "intuition": "Create deterministic pairwise preferences per instance by sorting candidates by objective (lower is better) and pairing adjacent ranks (best vs next-best, etc.) up to a per-instance cap; this avoids stratification complexity while preserving ranking intent and stability.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    # Deterministic per-instance cap; avoid using int() in restricted runtimes.
    max_pairs = extra.get('max_pairs_per_instance', 8)
    if max_pairs is None:
        max_pairs = 8
    # Coerce to a safe positive integer without calling int().
    try:
        max_pairs = max_pairs + 0
    except Exception:
        max_pairs = 8
    if max_pairs < 1:
        max_pairs = 1

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        scores = objective[b]
        if K < 2:
            continue
        order = scores.argsort(stable=True)
        # Pair adjacent ranks: (0 beats 1), (1 beats 2), ... up to cap.
        limit = max_pairs
        if limit > (K - 1):
            limit = K - 1
        for i in range(limit):
            w = order[i]
            l = order[i + 1]
            # Only emit when strictly better; avoids ambiguous ties.
            if scores[w].item() < scores[l].item():
                b_list.append(b)
                w_list.append(w.item())
                l_list.append(l.item())

    # Last resort: ensure at least one pair overall (gate requires >= 1).
    if len(b_list) == 0:
        for b in range(B):
            if K >= 2:
                b_list.append(b)
                w_list.append(0)
                l_list.append(1)
                break

    b_idx = objective.new_tensor(b_list, dtype=torch.long).view(-1)
    winner_idx = objective.new_tensor(w_list, dtype=torch.long).view(-1)
    loser_idx = objective.new_tensor(l_list, dtype=torch.long).view(-1)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={
            'builder': 'rank_adjacent_cap',
            'max_pairs_per_instance': max_pairs,
            'pairing': 'adjacent_ranks'
        }
    )
"
}

{
  "name": "rank_adjacent_cap_no_int",
  "intuition": "Sort each instance's candidates by objective (lower is better) and emit preferences between adjacent ranks up to a per-instance cap; ties are skipped to avoid ambiguous labels, and a fallback pair is added only if no strict improvements exist anywhere to satisfy the minimum-pairs gate.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    # Read cap without using int(); keep it as a small positive python number.
    max_pairs = extra.get('max_pairs_per_instance', 8)
    if max_pairs is None:
        max_pairs = 8
    try:
        max_pairs = max_pairs + 0
    except Exception:
        max_pairs = 8
    if max_pairs < 1:
        max_pairs = 1

    b_list = []
    w_list = []
    l_list = []

    if K >= 2:
        for b in range(B):
            scores = objective[b]
            order = scores.argsort(stable=True)
            limit = max_pairs
            if limit > (K - 1):
                limit = K - 1
            for i in range(limit):
                w = order[i]
                l = order[i + 1]
                # Only emit when strictly better to avoid tie ambiguity.
                if scores[w] < scores[l]:
                    b_list.append(b)
                    w_list.append(w)
                    l_list.append(l)

    # Ensure at least one pair overall.
    if len(b_list) == 0:
        if K >= 2 and B >= 1:
            b_list.append(0)
            w_list.append(objective.new_tensor(0, dtype=torch.long))
            l_list.append(objective.new_tensor(1, dtype=torch.long))

    b_idx = torch.stack([objective.new_tensor(x, dtype=torch.long) for x in b_list], dim=0).view(-1)
    winner_idx = torch.stack([objective.new_tensor(x, dtype=torch.long) for x in w_list], dim=0).view(-1)
    loser_idx = torch.stack([objective.new_tensor(x, dtype=torch.long) for x in l_list], dim=0).view(-1)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={
            'builder': 'rank_adjacent_cap_no_int',
            'max_pairs_per_instance': max_pairs,
            'pairing': 'adjacent_ranks'
        }
    )
"
