  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # lower objective is better; only keep pairs with a clear margin to reduce noisy supervision\n    gap_threshold = 0.0\n    if extra is not None and 'gap_threshold' in extra and extra['gap_threshold'] is not None:\n        gap_threshold = extra['gap_threshold']\n    gap = objective[:, :, None] - objective[:, None, :]\n    # winner i vs loser j when objective[i] < objective[j] - gap_threshold\n    mask = gap < (-gap_threshold)\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'gap_threshold_pairs', 'gap_threshold': gap_threshold})\n"
