{
  "name": "stratified_rank_pairs_norange",
  "intuition": "Create deterministic objective-based pairs without quadratic blowup by only comparing the best candidate to a small tail set plus a few adjacent mid-rank comparisons, with an optional objective-gap filter; implemented without Python builtins like range to avoid restricted-runtime failures.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better
    B = objective.shape[0]
    K = objective.shape[1]

    if extra is None:
        extra = {}

    max_pairs_per_instance = extra.get('max_pairs_per_instance', 8)
    if max_pairs_per_instance is None:
        max_pairs_per_instance = 8

    gap_threshold = extra.get('gap_threshold', 0)
    if gap_threshold is None:
        gap_threshold = 0

    tail_k = extra.get('tail_k', 3)
    mid_k = extra.get('mid_k', 3)
    if tail_k is None:
        tail_k = 3
    if mid_k is None:
        mid_k = 3

    order = objective.argsort(dim=1, descending=False)

    b_list = []
    w_list = []
    l_list = []

    b = 0
    while b < B:
        if K <= 1:
            b += 1
            continue

        ord_b = order[b]
        obj_b = objective[b]

        cap = int(max_pairs_per_instance)
        if cap <= 0:
            cap = 1

        pairs_used = 0

        # 1) Best vs tail
        best = ord_b[0]
        t = int(tail_k)
        if t < 1:
            t = 1
        if t > (K - 1):
            t = int(K - 1)

        i = 0
        while i < t and pairs_used < cap:
            tail = ord_b[K - 1 - i]
            if best != tail:
                if (obj_b[tail] - obj_b[best]) > gap_threshold:
                    b_list.append(int(b))
                    w_list.append(int(best))
                    l_list.append(int(tail))
                    pairs_used += 1
            i += 1

        # 2) Mid vs mid (adjacent ranks)
        if pairs_used < cap and K >= 3:
            mk = int(mid_k)
            if mk < 1:
                mk = 1
            if mk > K:
                mk = int(K)

            start = int((K - mk) // 2)
            if start < 0:
                start = 0
            end = start + int(mk)
            if end > K:
                end = int(K)

            r = start
            while (r + 1) < end and pairs_used < cap:
                w = ord_b[r]
                l = ord_b[r + 1]
                if w != l:
                    if (obj_b[l] - obj_b[w]) > gap_threshold:
                        b_list.append(int(b))
                        w_list.append(int(w))
                        l_list.append(int(l))
                        pairs_used += 1
                r += 1

        # 3) Ensure at least one decisive pair if any strict ordering exists
        if pairs_used == 0 and K >= 2:
            w = ord_b[0]
            l = ord_b[K - 1]
            if w != l and (obj_b[l] > obj_b[w]):
                b_list.append(int(b))
                w_list.append(int(w))
                l_list.append(int(l))

        b += 1

    device = objective.device
    idx_dtype = objective.new_empty((), dtype=objective.dtype).long().dtype

    if len(b_list) == 0:
        empty = objective.new_zeros((0,), dtype=idx_dtype)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={
                'builder': 'stratified_rank_pairs_norange',
                'gap_threshold': gap_threshold,
                'max_pairs_per_instance': max_pairs_per_instance,
                'tail_k': tail_k,
                'mid_k': mid_k,
            },
        )

    b_idx = objective.new_tensor(b_list, dtype=idx_dtype, device=device)
    w_idx = objective.new_tensor(w_list, dtype=idx_dtype, device=device)
    l_idx = objective.new_tensor(l_list, dtype=idx_dtype, device=device)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={
            'builder': 'stratified_rank_pairs_norange',
            'gap_threshold': gap_threshold,
            'max_pairs_per_instance': max_pairs_per_instance,
            'tail_k': tail_k,
            'mid_k': mid_k,
        },
    )"
}

