{
  "name": "builder_gap_threshold_weighted_004",
  "intuition": "Keep the gap-threshold filtering to avoid ambiguous near-ties, and additionally weight each retained comparison by its objective gap (beyond the threshold) so clearer winner/loser separations contribute more gradient signal while still staying nonnegative.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better; require a clear margin and weight by how clear it is
    gap_threshold = 0.0
    if extra is not None and 'gap_threshold' in extra and extra['gap_threshold'] is not None:
        gap_threshold = extra['gap_threshold']

    # gap[b,i,j] = obj[i] - obj[j]; winner i vs loser j when gap < -gap_threshold
    gap = objective[:, :, None] - objective[:, None, :]
    mask = gap < (-gap_threshold)
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)

    # Nonnegative weights: (obj_loser - obj_winner - threshold), clamped at 0.
    # This emphasizes more decisive comparisons without changing the preference direction.
    if b_idx.numel() == 0:
        weight = None
    else:
        g = (-gap[b_idx, winner_idx, loser_idx]) - gap_threshold
        weight = g.clamp_min(0.0)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=weight,
        meta={'builder': 'gap_threshold_weighted', 'gap_threshold': gap_threshold}
    )
