{
  "name": "builder_stratified_rank_pairs_cap_001",
  "intuition": "Build per-instance preferences from objective ranks (not raw gaps) using a stratified scheme: always compare near-best to mid and tail candidates plus a few mid-vs-tail pairs, with a hard cap per instance. This keeps clear ordering signal and full coverage while avoiding the O(K^2) explosion and reducing noisy adjacent-rank ties by skipping immediate neighbors.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    B, K = objective.shape

    # Config with safe defaults.
    max_pairs_per_instance = 32
    skip_neighbors = 1  # skip adjacent ranks to reduce near-ties without using raw gaps
    if extra is not None:
        if extra.get('max_pairs_per_instance', None) is not None:
            max_pairs_per_instance = int(extra['max_pairs_per_instance'])
        if extra.get('skip_neighbors', None) is not None:
            skip_neighbors = int(extra['skip_neighbors'])

    # Rank candidates by objective (lower is better).
    # order[b, r] = candidate index at rank r (0 is best).
    order = objective.argsort(dim=1)

    # Split ranks into strata.
    # near-best: first ~25%, mid: middle ~50%, tail: last ~25%.
    nb = K // 4
    tl = K // 4
    if nb < 1:
        nb = 1
    if tl < 1:
        tl = 1
    mid_start = nb
    mid_end = K - tl
    if mid_end <= mid_start:
        mid_start = 1
        mid_end = K - 1
    if mid_end <= mid_start:
        mid_start = 0
        mid_end = K

    b_out = []
    w_out = []
    l_out = []

    # Deterministic, capped pairing for each instance.
    for b in range(B):
        pairs_left = max_pairs_per_instance
        if pairs_left <= 0:
            continue

        # Helper to add a ranked pair (winner rank < loser rank).
        def add_pair(rw, rl):
            nonlocal pairs_left
            if pairs_left <= 0:
                return
            if rw < 0 or rl < 0 or rw >= K or rl >= K:
                return
            if rl <= rw:
                return
            if skip_neighbors is not None and skip_neighbors > 0:
                if rl - rw <= skip_neighbors:
                    return
            wi = order[b, rw].item()
            li = order[b, rl].item()
            b_out.append(b)
            w_out.append(wi)
            l_out.append(li)
            pairs_left -= 1

        # 1) Near-best vs Tail (clearest signal).
        for r in range(0, nb):
            if pairs_left <= 0:
                break
            add_pair(r, K - 1)

        # 2) Best vs a few mid anchors.
        if pairs_left > 0 and mid_end > mid_start:
            add_pair(0, mid_start)
            if pairs_left > 0:
                add_pair(0, (mid_start + mid_end - 1) // 2)
            if pairs_left > 0:
                add_pair(0, mid_end - 1)

        # 3) Mid vs Tail anchors.
        if pairs_left > 0 and mid_end > mid_start:
            add_pair(mid_start, K - 1)
            if pairs_left > 0:
                add_pair((mid_start + mid_end - 1) // 2, K - 1)
            if pairs_left > 0:
                add_pair(mid_end - 1, K - 1)

        # 4) If still budget, spread coverage by stepping through ranks.
        if pairs_left > 0:
            step = 1
            if K >= 8:
                step = 2
            for rw in range(0, K, step):
                if pairs_left <= 0:
                    break
                rl = K - 1 - rw
                if rl <= rw:
                    continue
                add_pair(rw, rl)

    # Convert to tensors on the same device as objective.
    device = objective.device
    if len(b_out) == 0:
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={
                'builder': 'stratified_rank_pairs_cap',
                'max_pairs_per_instance': max_pairs_per_instance,
                'skip_neighbors': skip_neighbors,
            },
        )

    b_idx = torch.tensor(b_out, device=device, dtype=torch.long)
    w_idx = torch.tensor(w_out, device=device, dtype=torch.long)
    l_idx = torch.tensor(l_out, device=device, dtype=torch.long)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={
            'builder': 'stratified_rank_pairs_cap',
            'max_pairs_per_instance': max_pairs_per_instance,
            'skip_neighbors': skip_neighbors,
            'strata': {'near_best': nb, 'mid': (mid_start, mid_end), 'tail': tl},
        },
    )
"
}

{
  "name": "builder_stratified_rank_pairs_simple_001",
  "intuition": "Create a small, deterministic set of clear rank-based comparisons per instance: best beats a few evenly-spaced anchors through the list (including tail), plus a couple mid-vs-tail anchors. This preserves strong ordering signal and broad coverage without relying on Python builtins like range/len that may be unavailable, and keeps pairs capped to avoid O(K^2).",
  "implementation_hint": {
    "expects": [
