{
  "name": "rank_stratified_cap_002",
  "intuition": "Keep deterministic objective-based supervision but avoid quadratic all-pairs by emitting a small, stratified set of rank-based comparisons per instance (extremes, near-best, mid-vs-tail, plus a few adjacent ranks) while optionally filtering near-ties via a configurable objective gap threshold.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better
    if extra is None:
        extra = {}

    gap_thr = extra.get('gap_threshold', 0.0)
    if gap_thr is None:
        gap_thr = 0.0

    max_pairs = extra.get('max_pairs_per_instance', 8)
    if max_pairs is None:
        max_pairs = 8
    try:
        max_pairs = int(max_pairs)
    except Exception:
        max_pairs = 8
    if max_pairs < 1:
        max_pairs = 1

    B, K = objective.shape[0], objective.shape[1]

    rank_pos = objective.argsort(dim=1, descending=False)

    b_list = []
    w_list = []
    l_list = []

    # Predefine deterministic strata by rank. Keep small to avoid O(K^2).
    cand_rank_pairs = []
    if K >= 2:
        cand_rank_pairs.append((0, K - 1))
        cand_rank_pairs.append((0, 1))
        cand_rank_pairs.append((K - 2, K - 1))
    if K >= 4:
        cand_rank_pairs.append((0, K // 2))
        cand_rank_pairs.append((K // 2 - 1, K - 1))
        cand_rank_pairs.append((1, K - 2))

    # Add a few adjacent comparisons for local signal.
    adj_limit = K - 1
    if adj_limit > max_pairs:
        adj_limit = max_pairs
    for r in range(adj_limit):
        cand_rank_pairs.append((r, r + 1))

    for b in range(B):
        if K < 2:
            continue
        added = 0

        # Always try the extreme pair first for coverage.
        w0 = rank_pos[b, 0]
        l0 = rank_pos[b, K - 1]
        if (objective[b, l0] - objective[b, w0]) > gap_thr:
            b_list.append(b)
            w_list.append(w0)
            l_list.append(l0)
            added += 1

        if added >= max_pairs:
            continue

        for wr, lr in cand_rank_pairs:
            if added >= max_pairs:
                break
            if wr < 0 or lr < 0 or wr >= K or lr >= K:
                continue
            if wr >= lr:
                continue
            w = rank_pos[b, wr]
            l = rank_pos[b, lr]
            if (objective[b, l] - objective[b, w]) <= gap_thr:
                continue
            b_list.append(b)
            w_list.append(w)
            l_list.append(l)
            added += 1

        # If gap filtering removed everything, fall back to a strict inequality extreme pair.
        if added == 0:
            w0 = rank_pos[b, 0]
            l0 = rank_pos[b, K - 1]
            if objective[b, w0] < objective[b, l0]:
                b_list.append(b)
                w_list.append(w0)
                l_list.append(l0)

    if len(b_list) == 0:
        empty = objective.new_zeros((0,), dtype=torch.int64)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'rank_stratified_cap', 'gap_threshold': gap_thr, 'max_pairs_per_instance': max_pairs},
        )

    b_idx = objective.new_tensor(b_list, dtype=torch.int64)
    w_idx = objective.new_tensor(w_list, dtype=torch.int64)
    l_idx = objective.new_tensor(l_list, dtype=torch.int64)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={'builder': 'rank_stratified_cap', 'gap_threshold': gap_thr, 'max_pairs_per_instance': max_pairs},
    )
