  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better

    gap_thr = 0.0
    topk = 4
    if extra is not None:
        if extra.get('gap_threshold', None) is not None:
            gap_thr = float(extra.get('gap_threshold'))
        if extra.get('topk', None) is not None:
            topk = int(extra.get('topk'))

    B, N = objective.shape
    if N <= 1:
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(mode='pairwise', pair_idx=(empty, empty, empty), weight=None, meta={'builder': 'gap_anchor_topk_pairs', 'gap_threshold': gap_thr, 'topk': topk})

    k = topk
    if k < 1:
        k = 1
    if k > N:
        k = N

    # anchors are the k best candidates per instance
    _, anchor_idx = ops.topk(-objective, k=k, dim=1, largest=True, sorted=False)

    # winners/losers by strict gap: objective[w] + gap_thr < objective[l]
    diff = objective[:, None, :] - objective[:, :, None]  # obj[l] - obj[w]
    mask = diff > gap_thr

