{
  "name": "gap_pairs_capped_simple_001",
  "intuition": "Create winner/loser pairs only when the objective margin exceeds a gap threshold (clear improvements), and cap the number of kept pairs per batch instance to prevent quadratic pair explosions from dominating training.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better

    if extra is None:
        extra = {}
    gap_thr = extra.get('gap_threshold', 0)
    max_pairs = extra.get('max_pairs_per_instance', extra.get('max_pairs', 2048))

    # diff[b,i,j] = obj[b,j] - obj[b,i]; positive => i better than j by that gap
    diff = objective[:, None, :] - objective[:, :, None]
    mask = diff > gap_thr
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)

    # Ensure int64, 1D
    b_idx = b_idx.to(dtype=objective.new_zeros((1,), dtype=objective.dtype).long().dtype).reshape(-1)
    winner_idx = winner_idx.to(dtype=b_idx.dtype).reshape(-1)
    loser_idx = loser_idx.to(dtype=b_idx.dtype).reshape(-1)

    if b_idx.numel() == 0:
        empty = objective.new_zeros((0,), dtype=b_idx.dtype).reshape(-1)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={
                'builder': 'gap_pairs_capped_simple',
                'gap_threshold': gap_thr,
                'max_pairs_per_instance': max_pairs,
            },
        )

    if max_pairs is not None and max_pairs > 0:
        keep = objective.new_zeros((b_idx.numel(),), dtype=objective.dtype).bool()
        counts = b_idx.new_zeros((int(objective.shape[0]),), dtype=b_idx.dtype)
        for k in range(b_idx.numel()):
            bi = int(b_idx[k].item())
            if counts[bi].item() < max_pairs:
                keep[k] = True
                counts[bi] = counts[bi] + 1
        b_idx = b_idx[keep]
        winner_idx = winner_idx[keep]
        loser_idx = loser_idx[keep]

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={
            'builder': 'gap_pairs_capped_simple',
            'gap_threshold': gap_thr,
            'max_pairs_per_instance': max_pairs,
        },
    )"
}

