{
  "name": "gap_anchor_topk_weighted_simple001",
  "intuition": "Prefer only clear objective improvements (gap > threshold) and restrict winners to the per-instance best/top-k anchors; weight each preference by the amount the winner beats the loser beyond the threshold, avoiding any Python builtins like int/float for stability.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better
    if extra is None:
        extra = {}

    gap_thr = extra.get('gap_threshold', 0)
    weight_scale = extra.get('weight_scale', 1.0)
    topk = extra.get('topk', 2)

    B = objective.shape[0]
    N = objective.shape[1]

    if B == 0 or N <= 1:
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=objective.new_zeros((0,)),
            meta={
                'builder': 'gap_anchor_topk_weighted_simple001',
                'gap_threshold': gap_thr,
                'weight_scale': weight_scale,
                'topk': topk,
            },
        )

    # Sanitize topk without using Python int().
    if topk is None:
        k = 1
    else:
        k = topk
    if k < 1:
        k = 1
    if k > N:
        k = N

    # diff[b,i,j] = obj[b,j] - obj[b,i]; positive means i is better than j by that gap.
    diff = objective[:, None, :] - objective[:, :, None]

    # Anchors are the k lowest objectives per instance.
    _, top_idx = objective.topk(k, dim=1, largest=False, sorted=True)

    # Mask only anchor winners vs all losers with clear gap.
    mask = diff > gap_thr
    mask_sel = mask.gather(1, top_idx[:, :, None].expand(B, k, N))

    b_idx, t_idx, loser_idx = mask_sel.nonzero(as_tuple=True)
    if b_idx.numel() == 0:
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=objective.new_zeros((0,)),
            meta={
                'builder': 'gap_anchor_topk_weighted_simple001',
                'gap_threshold': gap_thr,
                'weight_scale': weight_scale,
                'topk': k,
            },
        )

    winner_idx = top_idx[b_idx, t_idx]

    b_idx = b_idx.to(dtype=torch.long).reshape(-1)
    winner_idx = winner_idx.to(dtype=torch.long).reshape(-1)
    loser_idx = loser_idx.to(dtype=torch.long).reshape(-1)

    gap = diff[b_idx, winner_idx, loser_idx] - gap_thr
    weight = gap.clamp_min(0) * weight_scale

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=weight,
        meta={
            'builder': 'gap_anchor_topk_weighted_simple001',
            'gap_threshold': gap_thr,
            'weight_scale': weight_scale,
            'topk': k,
        },
    )"
