                'builder': 'rank_stratified_pairs_norange_001',
                'max_pairs_per_instance': max_pairs_per_instance,
                'near_k': near_k,
                'mid_k': mid_k,
                'tail_k': tail_k,
            },
        )

    order = objective.argsort(dim=1)  # [B, N]

    b_out = []
    w_out = []
    l_out = []
    wt_out = []

