        picked = 0

        k_near = near_k
        k_mid = mid_k
        k_tail = tail_k

        if k_near < 0:
            k_near = 0
        if k_mid < 0:
            k_mid = 0
        if k_tail < 0:
            k_tail = 0

        if k_near > N:
            k_near = N
        if k_tail > N:
            k_tail = N

        mid_start = (N // 2) - (k_mid // 2)
        if mid_start < 0:
            mid_start = 0
        mid_end = mid_start + k_mid
        if mid_end > N:
            mid_end = N

        # Adjacent pairs in each region using torch arange (avoid Python range).
        if picked < max_pairs_per_instance and k_near >= 2:
            rs = torch.arange(0, k_near - 1, device=objective.device, dtype=torch.long)
            for r in rs.tolist():
