                'mid_k': mid_k,
                'tail_k': tail_k,
            },
        )

    b_idx = objective.new_tensor(b_out, dtype=torch.long).reshape(-1)
    w_idx = objective.new_tensor(w_out, dtype=torch.long).reshape(-1)
    l_idx = objective.new_tensor(l_out, dtype=torch.long).reshape(-1)
