{
  "name": "stratified_rank_pairs_cap_001",
  "intuition": "Create robust, full-coverage preferences by ranking candidates per instance (lower objective is better) and pairing each rank position with a small stratified set of worse ranks (near, mid, tail). This preserves the parents' decisive ordering signal while avoiding the all-pairs quadratic explosion and reducing sensitivity to tiny objective gaps via rank-based comparisons and per-instance caps.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better
    if extra is None:
        extra = {}

    # Controls
    max_pairs_per_instance = extra.get('max_pairs_per_instance', 32)
    near_offsets = extra.get('near_offsets', [1, 2])
    mid_fracs = extra.get('mid_fracs', [0.25, 0.5])
    include_tail = extra.get('include_tail', True)

    B, K = objective.shape

    # Rank candidates per instance.
    # order[b, r] gives candidate index at rank r (r=0 is best).
    order = objective.argsort(dim=1)
    # inv_rank[b, i] gives rank of candidate i (0 is best).
    inv_rank = order.argsort(dim=1)

    # Collect pairs with full instance coverage: ensure at least one pair when K>=2.
    b_list = []
    w_list = []
    l_list = []
    wgt_list = []

    for b in range(B):
        if K < 2:
            continue

        pairs = 0

        # Helper to add a single rank-based pair (rb better than rl).
        def add_pair(rb, rl):
            nonlocal pairs
            if pairs >= max_pairs_per_instance:
                return
            if rb < 0 or rl < 0 or rb >= K or rl >= K:
                return
            if rb >= rl:
                return
            w = order[b, rb]
            l = order[b, rl]
            b_list.append(b)
            w_list.append(w)
            l_list.append(l)
            # Nonnegative weight: rank gap (>=1) emphasizes clearer separations without using raw objective gaps.
            wgt_list.append((rl - rb))
            pairs += 1

        # Always include an anchor pair for coverage: best vs worst.
        add_pair(0, K - 1)

        # Stratified: for each rank position, pair with near/mid/tail worse ranks.
        for rb in range(K):
            if pairs >= max_pairs_per_instance:
                break

            # Near-worse ranks
            for off in near_offsets:
                try:
                    off_i = int(off)
                except Exception:
                    continue
                add_pair(rb, rb + off_i)
                if pairs >= max_pairs_per_instance:
                    break
            if pairs >= max_pairs_per_instance:
                break

            # Mid ranks by fraction of the list
            for frac in mid_fracs:
                try:
                    f = float(frac)
                except Exception:
                    continue
                # Choose a worse rank at approximately this quantile.
                rl = int((K - 1) * f)
                if rl <= rb:
                    rl = rb + 1
                add_pair(rb, rl)
                if pairs >= max_pairs_per_instance:
                    break
            if pairs >= max_pairs_per_instance:
                break

            # Tail: pair with worst for a strong signal
            if include_tail:
                add_pair(rb, K - 1)

    # Build tensors (ensure correct dtype/device) and return.
    if len(b_list) == 0:
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=objective.new_zeros((0,)),
            meta={
                'builder': 'stratified_rank_pairs_cap_001',
                'max_pairs_per_instance': max_pairs_per_instance,
                'near_offsets': near_offsets,
                'mid_fracs': mid_fracs,
                'include_tail': include_tail,
            },
        )

    b_idx = torch.as_tensor(b_list, device=objective.device, dtype=torch.long)
    w_idx = torch.as_tensor(w_list, device=objective.device, dtype=torch.long)
    l_idx = torch.as_tensor(l_list, device=objective.device, dtype=torch.long)
    weight = torch.as_tensor(wgt_list, device=objective.device, dtype=objective.dtype).clamp_min(0)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=weight,
        meta={
            'builder': 'stratified_rank_pairs_cap_001',
            'max_pairs_per_instance': max_pairs_per_instance,
            'near_offsets': near_offsets,
