            num_mid = extra.get('num_mid')
        if extra.get('num_tail', None) is not None:
            num_tail = extra.get('num_tail')

    # Sort indices by objective ascending.
    order = objective.argsort(dim=1)

    pairs_b = []
    pairs_w = []
    pairs_l = []

    for b in range(B):
        k = int(K)
        if k < 2:
            continue

        # Clamp stratum sizes to valid ranges.
        t_top = int(num_top)
        t_mid = int(num_mid)
        t_tail = int(num_tail)

        if t_top < 1:
            t_top = 1
        if t_mid < 0:
            t_mid = 0
        if t_tail < 1:
            t_tail = 1

        if t_top > k - 1:
            t_top = k - 1
        if t_tail > k - 1:
            t_tail = k - 1

        # Mid stratum sits between top and tail.
        max_mid = k - t_top - t_tail
        if max_mid < 0:
            # If overlap would occur, reduce mid to 0.
