            max_pairs_per_instance = int(extra.get('max_pairs_per_instance'))

    B, K = objective.shape

    # Rank candidates per instance (ascending objective)
    order = objective.argsort(dim=1)  # [B, K], best to worst

    b_all = []
    w_all = []
    l_all = []

    # Helper to append a pair if it is a clear win under the objective-gap rule.
    def _maybe_add(b, wi, li):
        if wi == li:
            return False
        # clear win: obj[w] + gap_thr <= obj[l]
        if objective[b, wi] <= (objective[b, li] - gap_thr):
            b_all.append(b)
            w_all.append(wi)
            l_all.append(li)
            return True
        return False

    for b in range(B):
        pairs_used = 0
        # Indices in ranked order
