        best = order[b, 0].item()
        tail = order[b, K - 1].item()
        mid_pos = K // 2
        mid = order[b, mid_pos].item()

        # 1) Ensure coverage: try best vs worst first.
        if max_pairs_per_instance > 0:
            if _maybe_add(b, best, tail):
                pairs_used += 1

        # 2) Best vs a few tail elements (rank-based, not all pairs).
