                'gap_threshold': gap_thr,
                'max_pairs_per_instance': max_pairs_per_instance,
            },
        )

    b_idx = objective.new_tensor(b_all, dtype=torch.long)
    w_idx = objective.new_tensor(w_all, dtype=torch.long)
    l_idx = objective.new_tensor(l_all, dtype=torch.long)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={
            'builder': 'rank_stratified_cap_pairs',
            'gap_threshold': gap_thr,
