{
  "name": "stratified_rank_pairs_cap_v2",
  "intuition": "Create a small, deterministic set of informative per-instance comparisons by pairing sorted-by-objective ranks (best vs tail, best vs mid, mid vs tail, plus a few evenly spaced rank gaps) and then filtering out near-ties via a minimum objective margin, keeping pair counts bounded per instance.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    extra = {} if extra is None else extra

    gap_threshold = extra.get('gap_threshold', 0)
    max_pairs_per_instance = extra.get('max_pairs_per_instance', 64)

    B, K = objective.shape
    device = objective.device

    # Rank candidates per instance (ascending objective => best first).
    order = objective.argsort(dim=1)  # [B, K]

    # Build a small, deterministic list of rank-pairs.
    base_pairs = []
    if K >= 2:
        base_pairs.append((0, K - 1))
    if K >= 3:
        mid_r = K // 2
        base_pairs.append((0, mid_r))
        if mid_r != K - 1:
            base_pairs.append((mid_r, K - 1))

    # Add a few evenly spaced rank gaps if budget allows.
    if K >= 4:
        step = K // 4
        if step < 1:
            step = 1
        r = 0
        while (r + step) < K:
            # Keep list short: cap by max_pairs_per_instance if provided.
            if max_pairs_per_instance is not None:
                if not (len(base_pairs) < max_pairs_per_instance):
                    break
            base_pairs.append((r, r + step))
            r = r + step

    # Materialize winner/loser indices with margin filter.
    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        used = 0
        for rw, rl in base_pairs:
            if max_pairs_per_instance is not None:
                if used >= max_pairs_per_instance:
                    break
            if rw == rl:
                continue
            if rw < 0 or rl < 0 or rw >= K or rl >= K:
                continue

            wi = order[b, rw]
            li = order[b, rl]

            # Clear-win margin: loser objective must be larger than winner by > gap_threshold.
            if (objective[b, li] - objective[b, wi]) > gap_threshold:
