                w_list.append(wi)
                l_list.append(li)
                used = used + 1

    # Convert to 1D int64 tensors.
    if len(b_list) == 0:
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
