{
  "name": "builder_rank_stratified_pairs_001",
  "intuition": "Create clear-but-diverse supervision by ranking candidates per instance (lower objective is better) and pairing across strata: near-best vs near-best for fine discrimination, best vs mid/tail for strong signal, and mid vs tail to cover the full quality range; this avoids brittle raw-gap thresholds while enforcing full instance coverage with a per-instance pair cap.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']  # [B, K], lower is better

    # Pair budget controls: cap pairs per instance while ensuring coverage.
    max_pairs_per_instance = 32
    if extra is not None and extra.get('max_pairs_per_instance', None) is not None:
        max_pairs_per_instance = extra.get('max_pairs_per_instance')

    # Optional size of the "near-best" slice.
    near_best = 2
    if extra is not None and extra.get('near_best', None) is not None:
        near_best = extra.get('near_best')

    B, K = objective.shape

    # Deterministic rank ordering per instance; rank[0] is best (lowest objective).
    order = objective.argsort(dim=1)

    b_list = []
    w_list = []
    l_list = []

    # Helper: append a pair if we have budget.
    def _maybe_add(bi, wi, li, remaining):
        if remaining <= 0:
            return remaining
        if wi == li:
            return remaining
        b_list.append(bi)
        w_list.append(wi)
        l_list.append(li)
        return remaining - 1

    # Stratified, rank-based pairing.
    for b in range(B):
        remaining = max_pairs_per_instance
        ord_b = order[b]

        if K <= 1:
            continue

        # Choose representative indices by rank.
        best = ord_b[0]
        worst = ord_b[K - 1]
        mid = ord_b[K // 2]

        # Ensure at least one pair per instance (coverage), preferring strongest contrast.
        remaining = _maybe_add(b, best, worst, remaining)

        # Near-best vs near-best comparisons (fine-grained).
        nb = near_best
        if nb < 1:
            nb = 1
        if nb > K:
            nb = K
        for i in range(nb):
            wi = ord_b[i]
            for j in range(i + 1, nb):
                li = ord_b[j]
                remaining = _maybe_add(b, wi, li, remaining)
                if remaining <= 0:
                    break
            if remaining <= 0:
                break

        # Best vs mid and mid vs tail (diversity across the distribution).
        remaining = _maybe_add(b, best, mid, remaining)
        remaining = _maybe_add(b, mid, worst, remaining)

        # Add a few evenly spaced rank gaps: best vs selected tail positions.
        if remaining > 0 and K >= 4:
            # Deterministic tail anchors; avoids objective-gap sensitivity.
            anchors = [K - 1, (3 * K) // 4, K // 4]
            for pos in anchors:
                if pos < 0:
                    continue
                if pos >= K:
                    continue
                li = ord_b[pos]
                remaining = _maybe_add(b, best, li, remaining)
                if remaining <= 0:
                    break

    # If no pairs (e.g., B==0 or K<=1), still return a valid empty PrefBatch.
    if len(b_list) == 0:
        empty = objective.new_empty((0,), dtype=torch.long)
        meta = {
            'builder': 'rank_stratified_pairs',
            'max_pairs_per_instance': max_pairs_per_instance,
            'near_best': near_best
        }
        return PrefBatch(mode='pairwise', pair_idx=(empty, empty, empty), weight=None, meta=meta)

    b_idx = torch.stack(b_list).to(dtype=torch.long).view(-1)
    winner_idx = torch.stack(w_list).to(dtype=torch.long).view(-1)
    loser_idx = torch.stack(l_list).to(dtype=torch.long).view(-1)

    meta = {
        'builder': 'rank_stratified_pairs',
        'max_pairs_per_instance': max_pairs_per_instance,
        'near_best': near_best
    }
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta=meta)
